baseline.base:
def _heldout_same(x, y, atol):
    import math
    num = lambda v: isinstance(v, (int, float)) and not isinstance(v, bool)
    if num(x) and num(y) and (isinstance(x, float) or isinstance(y, float)):
        return math.isclose(x, y, rel_tol=1e-6, abs_tol=atol or 1e-6)
    if isinstance(x, (list, tuple)) and isinstance(y, (list, tuple)) and len(x) == len(y):
        return type(x) == type(y) and all(_heldout_same(a, b, atol) for a, b in zip(x, y))
    return x == y

def check(candidate):
    assert _heldout_same(candidate(3, 4, [[2, 1, 1]]), True, 0.0)
    assert _heldout_same(candidate(3, 3, [[1, 1, 2]]), False, 0.0)
    assert _heldout_same(candidate(3, 3, [[2, 1, 1], [1, 2, 1]]), False, 0.0)
    assert _heldout_same(candidate(4, 4, [[5, 5, 1]]), True, 0.0)

